"""Pure parser regression tests; importing the reader never opens a serial port."""
import importlib.util
from pathlib import Path
import unittest


spec = importlib.util.spec_from_file_location(
    'uwb_protocol_under_test', Path(__file__).with_name('uwb_usb_reader.py'))
reader = importlib.util.module_from_spec(spec)
spec.loader.exec_module(reader)

# Literal examples from specification V2.2, pages 10 and 11. These are
# independent byte fixtures, not packets generated by the parser under test.
POSITION_A = bytes.fromhex(
    'FF FF FF FF 00 25 00 0B 20 01 01 00 00 00 AA A2 00 00 AA A1 '
    '00 00 00 19 00 12 FF CA 12 34 00 0B 00 00 00 00 1E')
POSITION_B = bytes.fromhex(
    'FF FF FF FF 00 25 00 27 20 01 01 00 00 00 AA A2 00 00 AA A1 '
    '00 00 00 62 FF D9 00 0D 12 34 00 27 00 00 00 00 69')
HEARTBEAT = bytes.fromhex('FF FF FF FF 00 10 00 0B 20 02 01 01 00 00 AA A1')


def with_checksum(data):
    packet = bytearray(data)
    checksum = 0
    for value in packet[:-1]:
        checksum ^= value
    packet[-1] = checksum
    return bytes(packet)


class ProtocolV22Tests(unittest.TestCase):
    def test_official_positions_signed_angles_and_units(self):
        events = reader.AlxParser().feed(POSITION_A + POSITION_B)
        self.assertEqual(len(events), 2)
        self.assertEqual(
            [(e['distanceCm'], e['azimuthDeg'], e['elevationDeg']) for e in events],
            [(25, 18, -54), (98, -39, 13)])
        self.assertEqual([(e['anchorId'], e['tagId']) for e in events],
                         [(0xAAA2, 0xAAA1)] * 2)
        self.assertEqual([e['sequenceId'] for e in events], [11, 39])
        self.assertEqual([e['batchSn'] for e in events], [11, 39])
        self.assertEqual([e['tagStatus'] for e in events], [0x1234, 0x1234])
        self.assertTrue(all(e['protocolProfile'] == 'v2.2_documented' for e in events))

    def test_official_heartbeat_has_no_checksum_or_position(self):
        parser = reader.AlxParser()
        heartbeat, position = parser.feed(HEARTBEAT + POSITION_B)
        self.assertEqual(heartbeat['type'], 'heartbeat')
        self.assertEqual(heartbeat['anchorId'], 0xAAA1)
        self.assertEqual(heartbeat['version'], 0x0101)
        self.assertNotIn('tagId', heartbeat)
        self.assertNotIn('distanceCm', heartbeat)
        self.assertEqual(position['azimuthDeg'], -39)
        self.assertEqual(parser.counts['checksumErrors'], 0)
        self.assertEqual(parser.counts['heartbeatCount'], 1)

    def test_every_split_boundary_and_concatenated_frames(self):
        stream = POSITION_A + HEARTBEAT + POSITION_B
        expected = reader.AlxParser().feed(stream)
        for cut in range(len(stream) + 1):
            with self.subTest(cut=cut):
                parser = reader.AlxParser()
                self.assertEqual(parser.feed(stream[:cut]) + parser.feed(stream[cut:]), expected)
                self.assertEqual(parser.counts['goodCount'], 2)
                self.assertEqual(parser.counts['heartbeatCount'], 1)

    def test_bytewise_stream_with_noise_and_bad_checksum_recovers(self):
        damaged = bytearray(POSITION_A)
        damaged[24] ^= 1
        parser = reader.AlxParser()
        events = []
        for value in b'noise\xff\x00' + damaged + HEARTBEAT + POSITION_B:
            events.extend(parser.feed(bytes([value])))
        self.assertEqual([e['type'] for e in events], ['heartbeat', 'position'])
        self.assertEqual(events[-1]['distanceCm'], 98)
        self.assertEqual(parser.counts['checksumErrors'], 1)
        self.assertGreater(parser.counts['noiseBytes'], 0)

    def test_rejects_mismatched_heartbeat_length_and_version(self):
        short_0102 = bytearray(HEARTBEAT)
        short_0102[11] = 2
        long_0101 = bytearray(HEARTBEAT + b'\x00\x00')
        long_0101[5] = 18
        for invalid in (bytes(short_0102), with_checksum(long_0101)):
            with self.subTest(packet=invalid.hex()):
                parser = reader.AlxParser()
                events = parser.feed(invalid + POSITION_A)
                self.assertEqual([e['type'] for e in events], ['position'])
                self.assertEqual(parser.counts['unsupportedVersions'], 1)
                self.assertEqual(parser.counts['heartbeatCount'], 0)

    def test_unknown_format_does_not_block_next_frame(self):
        for offset, value in ((5, 40), (9, 3), (11, 9)):
            invalid = bytearray(POSITION_A)
            invalid[offset] = value
            parser = reader.AlxParser()
            events = parser.feed(bytes(invalid) + POSITION_B)
            self.assertEqual(len(events), 1)
            self.assertEqual(events[0]['sequenceId'], 39)
            self.assertIsNotNone(parser.last_unrecognized_header)

    def test_0102_compatibility_formats_remain_supported(self):
        position = bytearray(POSITION_B)
        position[11] = 2
        heartbeat = bytearray(HEARTBEAT + b'\x7A\x00')
        heartbeat[5] = 18
        heartbeat[11] = 2
        events = reader.AlxParser().feed(with_checksum(position) + with_checksum(heartbeat))
        self.assertEqual([e['type'] for e in events], ['position', 'heartbeat'])
        self.assertTrue(all(e['protocolProfile'] == '0102_compatibility' for e in events))
        self.assertEqual(events[0]['azimuthDeg'], -39)
        self.assertEqual(events[1]['reservedHex'], '7A')

    def test_0102_heartbeat_checksum_is_required(self):
        heartbeat = bytearray(HEARTBEAT + b'\x00\x00')
        heartbeat[5] = 18
        heartbeat[11] = 2
        heartbeat = bytearray(with_checksum(heartbeat))
        heartbeat[-1] ^= 1
        parser = reader.AlxParser()
        self.assertEqual(parser.feed(bytes(heartbeat)), [])
        self.assertEqual(parser.counts['checksumErrors'], 1)
        self.assertEqual(parser.counts['heartbeatCount'], 0)

    def test_unsigned_ids_range_and_unknown_reserved_bytes_preserved(self):
        position = bytearray(POSITION_A)
        position[12:24] = bytes.fromhex('FE DC BA 98 87 65 43 21 F0 00 00 01')
        position[28:30] = bytes.fromhex('80 01')
        position[32:36] = bytes.fromhex('01 23 AB CD')
        event = reader.AlxParser().feed(with_checksum(position))[0]
        self.assertEqual(event['anchorId'], 0xFEDCBA98)
        self.assertEqual(event['tagId'], 0x87654321)
        self.assertEqual(event['distanceCm'], 0xF0000001)
        self.assertEqual(event['tagStatus'], 0x8001)
        self.assertEqual(event['reservedHex'], '0123ABCD')

    def test_zero_range_preserved_without_inventing_offline_semantics(self):
        position = bytearray(POSITION_A)
        position[20:24] = b'\x00' * 4
        event = reader.AlxParser().feed(with_checksum(position))[0]
        self.assertEqual(event['type'], 'position')
        self.assertEqual(event['distanceCm'], 0)
        self.assertNotIn('online', event)


if __name__ == '__main__':
    unittest.main(verbosity=2)
